#!/usr/bin/env node
// Regenerates src/data/world-land.ts: an equirectangular SVG path of the
// Natural Earth 1:110m land outline (via the world-atlas TopoJSON package).
// Coordinates map lon/lat to x = lon + 180, y = 90 - lat in a 360x180 box.
// Run once; the generated file is committed so the site build stays offline.
import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const SOURCE = "https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/land-110m.json";
const OUTPUT = fileURLToPath(new URL("../src/data/world-land.ts", import.meta.url));

const response = await fetch(SOURCE);
if (!response.ok) throw new Error(`fetch ${SOURCE} -> ${response.status}`);
const topology = await response.json();

const { scale, translate } = topology.transform;
const arcs = topology.arcs.map((arc) => {
	let x = 0;
	let y = 0;
	return arc.map(([dx, dy]) => {
		x += dx;
		y += dy;
		return [x * scale[0] + translate[0], y * scale[1] + translate[1]];
	});
});

function ring(indexes) {
	const points = [];
	for (const index of indexes) {
		const arc = index < 0 ? arcs[~index].slice().reverse() : arcs[index];
		points.push(...(points.length ? arc.slice(1) : arc));
	}
	return points;
}

const fmt = (n) => Number(n.toFixed(1)).toString();

function ringPath(points) {
	let d = "";
	let previous = null;
	for (const [lon, lat] of points) {
		const x = fmt(lon + 180);
		const y = fmt(90 - lat);
		const key = `${x},${y}`;
		if (key === previous) continue;
		// Antimeridian jump: start a new subpath instead of drawing across the map.
		const jump = previous !== null && Math.abs(Number(previous.split(",")[0]) - Number(x)) > 180;
		d += `${d && !jump ? "L" : "M"}${x} ${y}`;
		previous = key;
	}
	return `${d}Z`;
}

const geometries = topology.objects.land.geometries;
let path = "";
for (const geometry of geometries) {
	const polygons = geometry.type === "Polygon" ? [geometry.arcs] : geometry.arcs;
	for (const polygon of polygons) {
		for (const indexes of polygon) path += ringPath(ring(indexes));
	}
}

const banner = `// Generated by scripts/build-world-map.mjs from ${SOURCE}\n// Natural Earth 1:110m land, public domain. Do not edit by hand.\n`;
await writeFile(OUTPUT, `${banner}export const WORLD_LAND_PATH =\n\t${JSON.stringify(path)};\n`);
console.log(`wrote ${OUTPUT} (${path.length} chars)`);
